  res_guide_palettes_body: {
    en: "Start from one base color and derive the rest: a complementary hue for accents, two or three neutrals for surfaces, and a spread of lightness steps for states. Keep the number of saturated colors small — most of the interface should be neutral, with saturation reserved for the elements you actually want people to notice.",
    fr: "Partez d'une couleur de base et déduisez le reste : une teinte complémentaire pour les accents, deux ou trois neutres pour les surfaces, et une échelle de luminosité pour les états. Limitez le nombre de couleurs saturées — l'essentiel de l'interface doit rester neutre, la saturation étant réservée à ce que l'on veut vraiment faire remarquer.",
    ar: "ابدأ من لون أساسي واشتقّ الباقي: لون مكمّل للتمييز، ولونان أو ثلاثة محايدة للأسطح، وسلّم إضاءة للحالات المختلفة. أبقِ الألوان المشبعة قليلة؛ فمعظم الواجهة ينبغي أن يكون محايدًا، والتشبع يُترك لما تريد لفت الانتباه إليه فعلًا.",
    es: "Empieza con un color base y deriva el resto: un tono complementario para acentos, dos o tres neutros para superficies y una gama de niveles de luminosidad para los estados. Mantén pocos colores saturados: la mayor parte de la interfaz debe ser neutra, reservando la saturación para lo que realmente quieres destacar.",
    de: "Beginnen Sie mit einer Basisfarbe und leiten Sie den Rest ab: ein komplementärer Farbton für Akzente, zwei oder drei neutrale Töne für Flächen und eine Reihe von Helligkeitsstufen für Zustände. Halten Sie die Anzahl gesättigter Farben gering — der Großteil der Oberfläche sollte neutral sein, Sättigung ist für Elemente reserviert, die wirklich auffallen sollen.",
    it: "Parti da un colore base e deriva il resto: una tonalità complementare per gli accenti, due o tre neutri per le superfici e una gamma di livelli di luminosità per gli stati. Mantieni pochi i colori saturi: la maggior parte dell'interfaccia dovrebbe essere neutra, riservando la saturazione a ciò che vuoi davvero far notare.",
    pt: "Comece com uma cor base e derive o resto: um matiz complementar para destaques, dois ou três neutros para superfícies e uma gama de níveis de luminosidade para estados. Mantenha poucas cores saturadas — a maior parte da interface deve ser neutra, reservando a saturação para o que você realmente quer destacar.",
    zh: "从一种基础色开始，推导出其余颜色：一个互补色相用于强调，两三个中性色用于表面，以及一系列明度用于状态变化。保持饱和色数量较少——界面大部分应为中性色，饱和度留给真正想突出的元素。",
    ja: "1つのベースカラーから始めて他を導き出します：アクセント用の補色、サーフェス用の2〜3の中間色、状態用の明度の幅。彩度の高い色は少なく保ちましょう。インターフェースの大部分は中間色にし、彩度は本当に目立たせたい要素のために取っておきます。",
    ko: "기본 색상 하나에서 시작해 나머지를 도출하세요: 강조용 보색 하나, 표면용 중성색 2~3개, 상태용 명도 단계. 채도가 높은 색상은 적게 유지하세요. 인터페이스 대부분은 중성색이어야 하며, 채도는 실제로 눈에 띄게 하고 싶은 요소를 위해 남겨두세요.",
    hi: "एक बेस रंग से शुरू करें और बाकी निकालें: एक्सेंट के लिए पूरक ह्यू, सतहों के लिए दो या तीन न्यूट्रल, और स्थितियों के लिए चमक के स्तर की एक श्रृंखला। संतृप्त रंगों की संख्या कम रखें — अधिकांश इंटरफेस न्यूट्रल होना चाहिए, संतृप्ति उन तत्वों के लिए आरक्षित रखें जिन्हें आप वास्तव में उजागर करना चाहते हैं।",
    tr: "Bir temel renkle başlayın ve gerisini türetin: vurgular için tamamlayıcı bir ton, yüzeyler için iki veya üç nötr renk ve durumlar için parlaklık kademeleri. Doygun renk sayısını az tutun — arayüzün çoğu nötr olmalı, doygunluk gerçekten dikkat çekmek istediğiniz öğeler için ayrılmalıdır.",
    pl: "Zacznij od jednego koloru bazowego i wyprowadź resztę: dopełniający odcień na akcenty, dwa lub trzy neutralne kolory na powierzchnie oraz zakres poziomów jasności na stany. Ogranicz liczbę nasyconych kolorów — większość interfejsu powinna być neutralna, a nasycenie zarezerwowane dla elementów, które naprawdę mają przyciągać uwagę.",
    nl: "Begin met één basiskleur en leid de rest af: een complementaire tint voor accenten, twee of drie neutrale kleuren voor oppervlakken, en een reeks helderheidsniveaus voor statussen. Houd het aantal verzadigde kleuren klein — het grootste deel van de interface moet neutraal zijn, met verzadiging gereserveerd voor elementen die echt moeten opvallen.",
    uk: "Почніть з одного базового кольору й виведіть решту: комплементарний тон для акцентів, два-три нейтральні кольори для поверхонь і діапазон рівнів світлості для станів. Тримайте кількість насичених кольорів невеликою — більша частина інтерфейсу має бути нейтральною, а насиченість — зарезервована для елементів, які справді мають привертати увагу.",
    vi: "Bắt đầu từ một màu cơ bản và suy ra phần còn lại: một sắc độ bổ sung cho điểm nhấn, hai hoặc ba màu trung tính cho bề mặt, và một dải mức độ sáng cho các trạng thái. Giữ số lượng màu bão hòa ít — phần lớn giao diện nên trung tính, độ bão hòa dành riêng cho những yếu tố bạn thực sự muốn người dùng chú ý.",
    th: "เริ่มจากสีพื้นฐานหนึ่งสีแล้วสร้างสีอื่นๆ ต่อ: เฉดสีตรงข้ามสำหรับจุดเน้น สีกลางสองหรือสามสีสำหรับพื้นผิว และช่วงระดับความสว่างสำหรับสถานะต่างๆ จำกัดจำนวนสีที่อิ่มตัวให้น้อย ส่วนใหญ่ของอินเทอร์เฟซควรเป็นสีกลาง โดยเก็บความอิ่มตัวไว้สำหรับองค์ประกอบที่ต้องการให้โดดเด่นจริงๆ",
    id: "Mulailah dengan satu warna dasar dan turunkan sisanya: satu rona komplementer untuk aksen, dua atau tiga warna netral untuk permukaan, dan rentang tingkat kecerahan untuk status. Jaga agar jumlah warna jenuh tetap sedikit — sebagian besar antarmuka harus netral, dengan saturasi disediakan untuk elemen yang benar-benar ingin Anda tonjolkan.",
    sv: "Börja med en basfärg och härled resten: en komplementär nyans för accenter, två eller tre neutrala färger för ytor och ett spann av ljushetsnivåer för tillstånd. Håll antalet mättade färger lågt — större delen av gränssnittet bör vara neutralt, med mättnad reserverad för element du verkligen vill att folk ska lägga märke till."
  },
