  res_guide_gradients_body: {
    en: "Gradients between colors far apart on the wheel pass through muddy midpoints. Keep the hue distance short, or add an intermediate stop that stays saturated. Interpolating in a perceptual space such as OKLCH gives noticeably cleaner results than plain sRGB, especially for long transitions across a large surface.",
    fr: "Un dégradé entre deux couleurs éloignées sur la roue traverse un milieu terne. Gardez une faible distance de teinte ou ajoutez une étape intermédiaire qui reste saturée. Une interpolation dans un espace perceptuel comme OKLCH donne un résultat nettement plus propre que le sRGB, surtout sur de longues transitions.",
    ar: "التدرّج بين لونين متباعدين على العجلة يمرّ بمنتصف باهت. أبقِ المسافة اللونية قصيرة أو أضف نقطة وسطى محتفظة بتشبعها. والاشتقاق في فضاء إدراكي مثل OKLCH يعطي نتيجة أنظف بكثير من sRGB، خصوصًا في الانتقالات الطويلة.",
    es: "Los degradados entre colores muy alejados en la rueda pasan por puntos medios turbios. Mantén corta la distancia de tono o añade una parada intermedia que se mantenga saturada. Interpolar en un espacio perceptual como OKLCH da resultados notablemente más limpios que sRGB, especialmente en transiciones largas sobre una superficie grande.",
    de: "Verläufe zwischen weit auseinanderliegenden Farben durchlaufen trübe Zwischenwerte. Halten Sie den Farbtonabstand gering oder fügen Sie einen Zwischenstopp hinzu, der gesättigt bleibt. Interpolation in einem Wahrnehmungsraum wie OKLCH liefert deutlich sauberere Ergebnisse als reines sRGB, besonders bei langen Übergängen über große Flächen.",
    it: "I gradienti tra colori lontani sulla ruota passano per punti intermedi fangosi. Mantieni breve la distanza di tonalità, oppure aggiungi un punto intermedio che resti saturo. L'interpolazione in uno spazio percettivo come OKLCH dà risultati notevolmente più puliti rispetto al semplice sRGB, specialmente per transizioni lunghe su superfici ampie.",
    pt: "Gradientes entre cores distantes na roda passam por pontos médios turvos. Mantenha curta a distância de matiz, ou adicione uma parada intermediária que permaneça saturada. Interpolar em um espaço perceptivo como OKLCH dá resultados visivelmente mais limpos do que sRGB simples, especialmente para transições longas em uma superfície grande.",
    zh: "色轮上相距较远的颜色之间的渐变会经过浑浊的中间色调。请保持色相距离较短，或添加一个保持饱和度的中间过渡点。在 OKLCH 等感知色彩空间中插值，效果明显比普通 sRGB 更干净，尤其是在大面积长渐变时。",
    ja: "カラーホイール上で離れた色同士のグラデーションは、濁った中間色を通ります。色相の距離を短く保つか、彩度を保つ中間ストップを追加しましょう。OKLCHのような知覚色空間での補間は、特に大きな面での長いグラデーションにおいて、単純なsRGBよりも明らかにきれいな結果を生みます。",
    ko: "색상환에서 멀리 떨어진 색상 간 그라데이션은 탁한 중간색을 지납니다. 색조 거리를 짧게 유지하거나 채도를 유지하는 중간 정지점을 추가하세요. OKLCH와 같은 지각 색공간에서 보간하면 단순 sRGB보다 눈에 띄게 깨끗한 결과를 얻을 수 있으며, 특히 큰 면적의 긴 전환에서 효과적입니다.",
    hi: "व्हील पर दूर के रंगों के बीच ग्रेडिएंट गंदे मध्यबिंदुओं से गुजरते हैं। ह्यू की दूरी कम रखें, या एक मध्यवर्ती स्टॉप जोड़ें जो संतृप्त बना रहे। OKLCH जैसे अवधारणात्मक स्थान में इंटरपोलेशन सामान्य sRGB की तुलना में काफी साफ परिणाम देता है, खासकर बड़े क्षेत्र में लंबे संक्रमणों के लिए।",
    tr: "Renk çarkında birbirinden uzak renkler arasındaki gradyanlar bulanık ara noktalardan geçer. Ton mesafesini kısa tutun veya doygun kalan bir ara durak ekleyin. OKLCH gibi algısal bir alanda enterpolasyon yapmak, özellikle büyük bir yüzeydeki uzun geçişlerde, düz sRGB'den belirgin şekilde daha temiz sonuçlar verir.",
    pl: "Gradienty między kolorami odległymi na kole przechodzą przez mętne punkty pośrednie. Zachowaj krótki dystans odcienia lub dodaj pośredni przystanek, który pozostaje nasycony. Interpolacja w przestrzeni percepcyjnej, takiej jak OKLCH, daje zauważalnie czystsze wyniki niż zwykły sRGB, szczególnie przy długich przejściach na dużej powierzchni.",
    nl: "Verlopen tussen kleuren die ver uit elkaar liggen op het wiel gaan door troebele middenpunten. Houd de tintafstand kort, of voeg een tussenstop toe die verzadigd blijft. Interpoleren in een perceptuele ruimte zoals OKLCH geeft merkbaar schonere resultaten dan gewone sRGB, vooral bij lange overgangen over een groot oppervlak.",
    uk: "Градієнти між далекими на колі кольорами проходять через каламутні проміжні точки. Тримайте відстань тону короткою або додайте проміжну зупинку, яка залишається насиченою. Інтерполяція в перцептивному просторі, як-от OKLCH, дає помітно чистіші результати, ніж звичайний sRGB, особливо для довгих переходів на великій поверхні.",
    vi: "Gradient giữa các màu cách xa nhau trên bánh xe màu đi qua các điểm giữa bị đục. Giữ khoảng cách sắc độ ngắn, hoặc thêm một điểm dừng trung gian vẫn giữ độ bão hòa. Nội suy trong không gian cảm nhận như OKLCH cho kết quả rõ ràng sạch hơn so với sRGB thông thường, đặc biệt với các chuyển tiếp dài trên bề mặt lớn.",
    th: "ไล่เฉดสีระหว่างสีที่ห่างกันมากบนวงล้อจะผ่านจุดกึ่งกลางที่ขุ่นมัว รักษาระยะห่างของเฉดสีให้สั้น หรือเพิ่มจุดหยุดกลางที่ยังคงความอิ่มตัว การประมาณค่าในพื้นที่การรับรู้อย่าง OKLCH ให้ผลลัพธ์ที่สะอาดกว่า sRGB ทั่วไปอย่างเห็นได้ชัด โดยเฉพาะการไล่เฉดยาวบนพื้นที่ขนาดใหญ่",
    id: "Gradien antara warna yang berjauhan pada roda melewati titik tengah yang keruh. Jaga jarak rona tetap pendek, atau tambahkan pemberhentian tengah yang tetap jenuh. Interpolasi dalam ruang persepsi seperti OKLCH memberikan hasil yang terlihat lebih bersih daripada sRGB biasa, terutama untuk transisi panjang pada permukaan besar.",
    sv: "Toningar mellan färger långt ifrån varandra på hjulet passerar genom grumliga mellanpunkter. Håll nyansavståndet kort, eller lägg till ett mellanstopp som förblir mättat. Interpolering i ett perceptuellt utrymme som OKLCH ger märkbart renare resultat än vanlig sRGB, särskilt för långa övergångar över en stor yta."
  },
