  res_asset_uikits_body: {
    en: "A UI kit is only as good as its color tokens. Define surfaces, borders, text levels and accents once, name them by role rather than by hue, and every component built on top stays consistent — and switching to a light or high-contrast theme becomes a matter of swapping values, not rewriting components.",
    fr: "Un kit UI ne vaut que par ses jetons de couleur. Définissez une fois les surfaces, les bordures, les niveaux de texte et les accents, nommez-les par leur rôle et non par leur teinte : tous les composants restent cohérents, et passer à un thème clair ou très contrasté revient à changer des valeurs, pas à réécrire les composants.",
    ar: "قيمة طقم الواجهة في رموز ألوانه. عرّف الأسطح والحدود ومستويات النص وألوان التمييز مرة واحدة، وسمِّها بحسب وظيفتها لا بحسب درجتها؛ عندئذ تبقى المكوّنات متسقة، ويصبح التحويل إلى سمة فاتحة أو عالية التباين مجرد تبديل قيم لا إعادة كتابة.",
    es: "Un kit de interfaz es tan bueno como sus tokens de color. Define superficies, bordes, niveles de texto y acentos una sola vez, nómbralos por función y no por tono, y cada componente construido encima se mantendrá coherente; cambiar a un tema claro o de alto contraste se convierte en solo intercambiar valores, no en reescribir componentes.",
    de: "Ein UI-Kit ist nur so gut wie seine Farb-Tokens. Definieren Sie Flächen, Ränder, Textstufen und Akzente einmal, benennen Sie sie nach Rolle statt nach Farbton, und jede darauf aufbauende Komponente bleibt konsistent — der Wechsel zu einem hellen oder kontrastreichen Theme wird so zum reinen Werteaustausch statt zum Umschreiben von Komponenten.",
    it: "Un kit UI vale quanto i suoi token di colore. Definisci superfici, bordi, livelli di testo e accenti una sola volta, nominandoli per ruolo anziché per tonalità, e ogni componente costruito sopra rimarrà coerente — passare a un tema chiaro o ad alto contrasto diventa solo una questione di scambiare valori, non di riscrivere componenti.",
    pt: "Um kit de UI é tão bom quanto seus tokens de cor. Defina superfícies, bordas, níveis de texto e destaques uma vez, nomeando-os pela função em vez do tom, e cada componente construído sobre eles permanece consistente — mudar para um tema claro ou de alto contraste se torna apenas uma troca de valores, não uma reescrita de componentes.",
    zh: "UI 套件的好坏取决于其颜色令牌。只需定义一次表面、边框、文本层级和强调色，按角色而非色相命名，构建在其上的每个组件都会保持一致——切换到浅色或高对比度主题只需替换数值，无需重写组件。",
    ja: "UIキットの良し悪しはカラートークン次第です。サーフェス、ボーダー、テキストレベル、アクセントを一度定義し、色相ではなく役割で命名すれば、その上に構築されたすべてのコンポーネントが一貫性を保ちます。ライトテーマや高コントラストテーマへの切り替えも、コンポーネントの書き直しではなく値の入れ替えだけで済みます。",
    ko: "UI 키트는 색상 토큰만큼만 좋습니다. 표면, 테두리, 텍스트 수준, 강조색을 한 번 정의하고 색조가 아닌 역할별로 이름을 지정하면 그 위에 구축된 모든 구성 요소가 일관성을 유지합니다. 밝은 테마나 고대비 테마로 전환하는 것도 구성 요소를 다시 작성하는 것이 아니라 값을 교체하는 것만으로 가능해집니다.",
    hi: "UI किट उतना ही अच्छा है जितने उसके रंग टोकन। सतहों, बॉर्डर, टेक्स्ट स्तरों और एक्सेंट को एक बार परिभाषित करें, उन्हें ह्यू के बजाय भूमिका से नाम दें, और उसके ऊपर बना हर घटक सुसंगत रहेगा — हल्के या उच्च-कंट्रास्ट थीम में बदलना घटकों को फिर से लिखने के बजाय बस मानों को बदलने का मामला बन जाता है।",
    tr: "Bir UI kiti ancak renk belirteçleri kadar iyidir. Yüzeyleri, kenarlıkları, metin seviyelerini ve vurguları bir kez tanımlayın, tona göre değil role göre adlandırın; böylece üzerine inşa edilen her bileşen tutarlı kalır — açık veya yüksek kontrastlı bir temaya geçmek, bileşenleri yeniden yazmak yerine sadece değerleri değiştirmek haline gelir.",
    pl: "Zestaw UI jest tak dobry, jak jego tokeny kolorów. Zdefiniuj powierzchnie, obramowania, poziomy tekstu i akcenty raz, nazywając je według roli, a nie odcienia, a każdy zbudowany na nich komponent pozostanie spójny — przejście na jasny lub wysokokontrastowy motyw staje się kwestią zamiany wartości, a nie przepisywania komponentów.",
    nl: "Een UI-kit is slechts zo goed als zijn kleurtokens. Definieer oppervlakken, randen, tekstniveaus en accenten één keer, noem ze naar rol in plaats van tint, en elk component dat erop wordt gebouwd blijft consistent — overschakelen naar een licht of hoog-contrastthema wordt dan een kwestie van waarden verwisselen, niet van componenten herschrijven.",
    uk: "UI-набір настільки хороший, наскільки хороші його кольорові токени. Визначте поверхні, межі, рівні тексту та акценти один раз, називайте їх за роллю, а не за тоном, і кожен побудований на них компонент залишатиметься узгодженим — перехід на світлу чи високо контрастну тему стає просто заміною значень, а не переписуванням компонентів.",
    vi: "Bộ UI chỉ tốt bằng các token màu của nó. Định nghĩa bề mặt, viền, mức văn bản và điểm nhấn một lần, đặt tên theo vai trò thay vì sắc độ, và mọi thành phần xây dựng trên đó sẽ luôn nhất quán — chuyển sang giao diện sáng hoặc tương phản cao chỉ đơn giản là hoán đổi giá trị, không cần viết lại thành phần.",
    th: "UI Kit จะดีได้เท่ากับโทเค็นสีของมันเท่านั้น กำหนดพื้นผิว ขอบ ระดับข้อความ และสีเน้นเพียงครั้งเดียว ตั้งชื่อตามบทบาทแทนที่จะเป็นเฉดสี แล้วทุกคอมโพเนนต์ที่สร้างขึ้นบนนั้นจะยังคงสอดคล้องกัน การเปลี่ยนไปใช้ธีมสว่างหรือคอนทราสต์สูงจะกลายเป็นเพียงการสลับค่า ไม่ใช่การเขียนคอมโพเนนต์ใหม่",
    id: "Kit UI hanya sebaik token warnanya. Tentukan permukaan, batas, level teks, dan aksen sekali, beri nama berdasarkan peran bukan rona, dan setiap komponen yang dibangun di atasnya akan tetap konsisten — beralih ke tema terang atau kontras tinggi menjadi soal menukar nilai, bukan menulis ulang komponen.",
    sv: "Ett UI-kit är bara så bra som dess färgtoken. Definiera ytor, kanter, textnivåer och accenter en gång, namnge dem efter roll snarare än nyans, så förblir varje komponent byggd ovanpå konsekvent — att byta till ett ljust eller högkontrastigt tema blir bara en fråga om att byta värden, inte skriva om komponenter."
  },
