  res_help_docs_body: {
    en: "Every page of the app works offline and stores your palettes, saved colors and presets in the browser. Clearing site data resets them, so export anything you want to keep as JSON from the Export menu before wiping your browser storage.",
    fr: "Toutes les pages fonctionnent hors ligne et conservent vos palettes, vos couleurs enregistrées et vos préréglages dans le navigateur. Effacer les données du site les supprime : exportez en JSON ce que vous voulez garder via le menu Exporter.",
    ar: "تعمل جميع الصفحات دون اتصال وتحفظ لوحاتك وألوانك المحفوظة وإعداداتك داخل المتصفح. ومسح بيانات الموقع يحذفها، لذا صدّر ما يهمّك بصيغة JSON من قائمة «تصدير».",
    es: "Cada página de la app funciona sin conexión y guarda tus paletas, colores guardados y preajustes en el navegador. Borrar los datos del sitio los reinicia, así que exporta cualquier cosa que quieras conservar como JSON desde el menú Exportar antes de borrar el almacenamiento del navegador.",
    de: "Jede Seite der App funktioniert offline und speichert Ihre Paletten, gespeicherten Farben und Vorlagen im Browser. Das Löschen der Website-Daten setzt diese zurück. Exportieren Sie daher alles, was Sie behalten möchten, als JSON über das Exportmenü, bevor Sie den Browserspeicher löschen.",
    it: "Ogni pagina dell'app funziona offline e memorizza le tue palette, colori salvati e preset nel browser. La cancellazione dei dati del sito li reimposta, quindi esporta tutto ciò che vuoi conservare come JSON dal menu Esporta prima di cancellare l'archivio del browser.",
    pt: "Cada página do app funciona offline e armazena suas paletas, cores salvas e predefinições no navegador. Limpar os dados do site os reinicia, então exporte qualquer coisa que queira manter como JSON pelo menu Exportar antes de apagar o armazenamento do navegador.",
    zh: "应用的每个页面均可离线运行，并将您的调色板、已保存颜色和预设存储在浏览器中。清除网站数据会重置它们，因此在清除浏览器存储之前，请通过导出菜单将想保留的内容导出为 JSON。",
    ja: "アプリの各ページはオフラインで動作し、パレット、保存した色、プリセットをブラウザに保存します。サイトデータを消去するとリセットされるため、ブラウザストレージを消去する前に、保持したい内容をエクスポートメニューからJSONとして書き出してください。",
    ko: "앱의 모든 페이지는 오프라인에서 작동하며 팔레트, 저장된 색상 및 사전 설정을 브라우저에 저장합니다. 사이트 데이터를 지우면 초기화되므로 브라우저 저장소를 지우기 전에 내보내기 메뉴에서 유지하고 싶은 항목을 JSON으로 내보내세요.",
    hi: "ऐप का हर पेज ऑफ़लाइन काम करता है और आपके पैलेट, सहेजे गए रंग और प्रीसेट ब्राउज़र में संग्रहीत करता है। साइट डेटा साफ करने से ये रीसेट हो जाते हैं, इसलिए ब्राउज़र स्टोरेज मिटाने से पहले जो कुछ रखना चाहते हैं उसे एक्सपोर्ट मेनू से JSON के रूप में एक्सपोर्ट करें।",
    tr: "Uygulamanın her sayfası çevrimdışı çalışır ve palet, kayıtlı renk ve ön ayarlarınızı tarayıcıda saklar. Site verilerini temizlemek bunları sıfırlar, bu yüzden tarayıcı depolamasını silmeden önce saklamak istediğiniz her şeyi Dışa Aktar menüsünden JSON olarak dışa aktarın.",
    pl: "Każda strona aplikacji działa offline i przechowuje Twoje palety, zapisane kolory i ustawienia w przeglądarce. Wyczyszczenie danych witryny je resetuje, więc wyeksportuj wszystko, co chcesz zachować, jako JSON z menu Eksportuj przed wyczyszczeniem pamięci przeglądarki.",
    nl: "Elke pagina van de app werkt offline en slaat je paletten, opgeslagen kleuren en voorinstellingen op in de browser. Het wissen van sitegegevens reset deze, dus exporteer alles wat je wilt behouden als JSON via het Exporteren-menu voordat je de browseropslag wist.",
    uk: "Кожна сторінка застосунку працює офлайн і зберігає ваші палітри, збережені кольори та пресети в браузері. Очищення даних сайту скидає їх, тому експортуйте все, що хочете зберегти, у форматі JSON через меню Експорт перед очищенням сховища браузера.",
    vi: "Mọi trang của ứng dụng hoạt động ngoại tuyến và lưu trữ bảng màu, màu đã lưu và cài đặt sẵn của bạn trong trình duyệt. Xóa dữ liệu trang web sẽ đặt lại chúng, vì vậy hãy xuất bất kỳ thứ gì bạn muốn giữ dưới dạng JSON từ menu Xuất trước khi xóa bộ nhớ trình duyệt.",
    th: "ทุกหน้าของแอปทำงานแบบออฟไลน์และเก็บจานสี สีที่บันทึกไว้ และค่าที่ตั้งไว้ล่วงหน้าไว้ในเบราว์เซอร์ การล้างข้อมูลเว็บไซต์จะรีเซ็ตสิ่งเหล่านี้ ดังนั้นควรส่งออกสิ่งที่ต้องการเก็บไว้เป็น JSON จากเมนูส่งออกก่อนล้างที่เก็บข้อมูลเบราว์เซอร์",
    id: "Setiap halaman aplikasi bekerja secara offline dan menyimpan palet, warna tersimpan, dan preset Anda di browser. Menghapus data situs akan mengatur ulang semuanya, jadi ekspor apa pun yang ingin Anda simpan sebagai JSON dari menu Ekspor sebelum menghapus penyimpanan browser.",
    sv: "Varje sida i appen fungerar offline och lagrar dina paletter, sparade färger och förval i webbläsaren. Att rensa webbplatsdata återställer dem, så exportera allt du vill behålla som JSON från Exportera-menyn innan du rensar webbläsarlagringen."
  },
