  res_help_faq_body: {
    en: "Why does the eyedropper only work in some browsers? It relies on the EyeDropper API, which Chrome and Edge support but Firefox and Safari do not. Why does a contrast ratio differ from another tool? Some checkers round differently or measure against a different background — the formula here follows WCAG 2.1 exactly.",
    fr: "Pourquoi la pipette ne fonctionne-t-elle pas partout ? Elle repose sur l'API EyeDropper, prise en charge par Chrome et Edge mais pas par Firefox ni Safari. Pourquoi le rapport de contraste diffère-t-il d'un autre outil ? Certains arrondissent autrement ou mesurent sur un autre fond ; ici la formule suit exactement WCAG 2.1.",
    ar: "لماذا لا تعمل القطّارة في كل المتصفحات؟ لأنها تعتمد على واجهة EyeDropper التي يدعمها Chrome وEdge دون Firefox وSafari. ولماذا تختلف نسبة التباين عن أداة أخرى؟ لأن بعض الأدوات تقرّب الأرقام أو تقيس على خلفية مختلفة، بينما المعادلة هنا تتبع WCAG 2.1 بدقّة.",
    es: "¿Por qué el gotero solo funciona en algunos navegadores? Depende de la API EyeDropper, que Chrome y Edge admiten pero Firefox y Safari no. ¿Por qué la relación de contraste difiere de otra herramienta? Algunos verificadores redondean de forma distinta o miden contra un fondo diferente; la fórmula aquí sigue exactamente WCAG 2.1.",
    de: "Warum funktioniert die Pipette nur in einigen Browsern? Sie basiert auf der EyeDropper-API, die von Chrome und Edge, aber nicht von Firefox und Safari unterstützt wird. Warum weicht ein Kontrastverhältnis von einem anderen Tool ab? Manche Prüfer runden anders oder messen gegen einen anderen Hintergrund — die hier verwendete Formel folgt exakt WCAG 2.1.",
    it: "Perché il contagocce funziona solo in alcuni browser? Si basa sull'API EyeDropper, supportata da Chrome ed Edge ma non da Firefox e Safari. Perché un rapporto di contrasto differisce da un altro strumento? Alcuni verificatori arrotondano diversamente o misurano rispetto a uno sfondo diverso: la formula qui segue esattamente WCAG 2.1.",
    pt: "Por que o conta-gotas só funciona em alguns navegadores? Ele depende da API EyeDropper, suportada pelo Chrome e Edge, mas não pelo Firefox e Safari. Por que uma razão de contraste difere de outra ferramenta? Alguns verificadores arredondam de forma diferente ou medem contra um fundo diferente — a fórmula aqui segue exatamente o WCAG 2.1.",
    zh: "为什么取色器只在部分浏览器中可用？它依赖于 EyeDropper API，该 API 受 Chrome 和 Edge 支持，但 Firefox 和 Safari 不支持。为什么对比度与其他工具不同？某些检测工具的四舍五入方式不同，或基于不同背景测量——此处公式严格遵循 WCAG 2.1。",
    ja: "なぜスポイトは一部のブラウザでしか動作しないのですか？EyeDropper APIに依存しており、ChromeとEdgeはサポートしていますが、FirefoxとSafariはサポートしていません。なぜコントラスト比が他のツールと異なるのですか？チェッカーによって丸め方や比較する背景が異なる場合があります。ここでの計算式はWCAG 2.1に厳密に従っています。",
    ko: "스포이드가 일부 브라우저에서만 작동하는 이유는 무엇인가요? Chrome과 Edge는 지원하지만 Firefox와 Safari는 지원하지 않는 EyeDropper API에 의존하기 때문입니다. 명암비가 다른 도구와 다른 이유는 무엇인가요? 일부 검사기는 반올림 방식이 다르거나 다른 배경을 기준으로 측정합니다. 여기의 공식은 WCAG 2.1을 정확히 따릅니다.",
    hi: "आईड्रॉपर केवल कुछ ब्राउज़रों में ही क्यों काम करता है? यह EyeDropper API पर निर्भर करता है, जिसे Chrome और Edge समर्थन देते हैं लेकिन Firefox और Safari नहीं। कंट्रास्ट अनुपात दूसरे टूल से अलग क्यों है? कुछ चेकर अलग तरह से राउंड करते हैं या अलग पृष्ठभूमि के मुकाबले मापते हैं — यहां का फॉर्मूला ठीक WCAG 2.1 का पालन करता है।",
    tr: "Damlalık neden yalnızca bazı tarayıcılarda çalışır? Chrome ve Edge'in desteklediği ancak Firefox ve Safari'nin desteklemediği EyeDropper API'sine dayanır. Kontrast oranı neden başka bir araçtan farklı? Bazı denetleyiciler farklı yuvarlar veya farklı bir arka plana göre ölçer — buradaki formül tam olarak WCAG 2.1'i takip eder.",
    pl: "Dlaczego kroplomierz działa tylko w niektórych przeglądarkach? Opiera się na API EyeDropper, obsługiwanym przez Chrome i Edge, ale nie przez Firefox i Safari. Dlaczego współczynnik kontrastu różni się od innego narzędzia? Niektóre narzędzia zaokrąglają inaczej lub mierzą względem innego tła — formuła tutaj dokładnie odpowiada WCAG 2.1.",
    nl: "Waarom werkt de pipet alleen in sommige browsers? Het is afhankelijk van de EyeDropper API, die door Chrome en Edge wordt ondersteund maar niet door Firefox en Safari. Waarom verschilt een contrastverhouding van een andere tool? Sommige checkers ronden anders af of meten tegen een andere achtergrond — de formule hier volgt precies WCAG 2.1.",
    uk: "Чому піпетка працює лише в деяких браузерах? Вона залежить від API EyeDropper, який підтримують Chrome і Edge, але не Firefox і Safari. Чому коефіцієнт контрастності відрізняється від іншого інструменту? Деякі перевірки округлюють по-іншому або вимірюють на іншому фоні — формула тут точно відповідає WCAG 2.1.",
    vi: "Tại sao công cụ hút màu chỉ hoạt động trên một số trình duyệt? Nó phụ thuộc vào API EyeDropper, được Chrome và Edge hỗ trợ nhưng Firefox và Safari thì không. Tại sao tỷ lệ tương phản khác với công cụ khác? Một số công cụ kiểm tra làm tròn khác nhau hoặc đo trên nền khác — công thức ở đây tuân theo chính xác WCAG 2.1.",
    th: "เหตุใดที่หยดสีจึงทำงานได้เฉพาะในบางเบราว์เซอร์ เนื่องจากใช้ EyeDropper API ซึ่ง Chrome และ Edge รองรับแต่ Firefox และ Safari ไม่รองรับ เหตุใดอัตราส่วนคอนทราสต์จึงต่างจากเครื่องมืออื่น เครื่องมือตรวจสอบบางตัวปัดเศษต่างกันหรือวัดกับพื้นหลังต่างกัน สูตรที่นี่เป็นไปตาม WCAG 2.1 อย่างเคร่งครัด",
    id: "Mengapa pipet warna hanya berfungsi di beberapa browser? Ini bergantung pada API EyeDropper, yang didukung Chrome dan Edge tetapi tidak Firefox dan Safari. Mengapa rasio kontras berbeda dari alat lain? Beberapa pemeriksa membulatkan secara berbeda atau mengukur terhadap latar yang berbeda — rumus di sini mengikuti persis WCAG 2.1.",
    sv: "Varför fungerar pipetten bara i vissa webbläsare? Den bygger på EyeDropper-API:et, som stöds av Chrome och Edge men inte Firefox och Safari. Varför skiljer sig ett kontrastförhållande från ett annat verktyg? Vissa kontroller avrundar annorlunda eller mäter mot en annan bakgrund — formeln här följer exakt WCAG 2.1."
  },
