  res_help_issue_body: {
    en: "A useful bug report needs three things: what you did, what you expected, and what happened instead. Add your browser and version, and a HEX value if the problem involves a specific color — that is usually enough to reproduce the issue on the first try.",
    fr: "Un bon rapport de bug contient trois éléments : ce que vous avez fait, ce que vous attendiez et ce qui s'est produit. Ajoutez votre navigateur et sa version, ainsi que la valeur HEX si le problème concerne une couleur précise — cela suffit généralement à reproduire le cas du premier coup.",
    ar: "البلاغ المفيد يتضمّن ثلاثة أمور: ما الذي فعلته، وما الذي توقّعته، وما الذي حدث فعلًا. أضف اسم المتصفح وإصداره، وقيمة HEX إن كانت المشكلة مرتبطة بلون بعينه؛ يكفي هذا عادةً لإعادة إنتاج المشكلة من أول محاولة.",
    es: "Un informe de error útil necesita tres cosas: qué hiciste, qué esperabas y qué ocurrió en su lugar. Añade tu navegador y versión, y un valor HEX si el problema implica un color específico; suele bastar para reproducir el problema al primer intento.",
    de: "Ein nützlicher Fehlerbericht braucht drei Dinge: was Sie getan haben, was Sie erwartet haben und was stattdessen passiert ist. Fügen Sie Ihren Browser und dessen Version sowie einen HEX-Wert hinzu, falls das Problem eine bestimmte Farbe betrifft — das reicht meist, um das Problem beim ersten Versuch zu reproduzieren.",
    it: "Una segnalazione di bug utile richiede tre cose: cosa hai fatto, cosa ti aspettavi e cosa è successo invece. Aggiungi il tuo browser e la versione, e un valore HEX se il problema riguarda un colore specifico — di solito basta per riprodurre il problema al primo tentativo.",
    pt: "Um relatório de bug útil precisa de três coisas: o que você fez, o que esperava e o que aconteceu em vez disso. Adicione seu navegador e versão, e um valor HEX se o problema envolver uma cor específica — geralmente isso basta para reproduzir o problema na primeira tentativa.",
    zh: "一份有用的错误报告需要三点：您做了什么、您期望什么，以及实际发生了什么。请附上浏览器及版本，如果问题涉及特定颜色，也请附上 HEX 值——通常这样就足以在第一次尝试时重现问题。",
    ja: "役立つバグレポートには3つの要素が必要です：何をしたか、何を期待していたか、代わりに何が起きたか。ブラウザとバージョンを追加し、問題が特定の色に関わる場合はHEX値も加えてください。これで通常、初回で問題を再現するのに十分です。",
    ko: "유용한 버그 보고서에는 세 가지가 필요합니다: 무엇을 했는지, 무엇을 예상했는지, 대신 무슨 일이 일어났는지. 브라우저와 버전을 추가하고, 문제가 특정 색상과 관련된 경우 HEX 값을 추가하세요. 보통 이것만으로 첫 시도에 문제를 재현하기에 충분합니다.",
    hi: "एक उपयोगी बग रिपोर्ट को तीन चीजों की जरूरत है: आपने क्या किया, आपने क्या उम्मीद की थी, और इसके बजाय क्या हुआ। अपना ब्राउज़र और वर्जन जोड़ें, और यदि समस्या किसी विशेष रंग से जुड़ी है तो HEX मान जोड़ें — यह आमतौर पर पहली बार में समस्या को दोहराने के लिए पर्याप्त है।",
    tr: "Yararlı bir hata raporu üç şeye ihtiyaç duyar: ne yaptığınız, ne beklediğiniz ve bunun yerine ne olduğu. Tarayıcınızı ve sürümünüzü ve sorun belirli bir renkle ilgiliyse bir HEX değerini ekleyin — bu genellikle sorunu ilk denemede yeniden oluşturmaya yeter.",
    pl: "Przydatne zgłoszenie błędu wymaga trzech rzeczy: co zrobiłeś, czego oczekiwałeś i co się stało zamiast tego. Dodaj przeglądarkę i wersję oraz wartość HEX, jeśli problem dotyczy konkretnego koloru — zwykle to wystarczy, aby odtworzyć problem za pierwszym razem.",
    nl: "Een nuttig bugrapport heeft drie dingen nodig: wat je deed, wat je verwachtte en wat er in plaats daarvan gebeurde. Voeg je browser en versie toe, en een HEX-waarde als het probleem een specifieke kleur betreft — dat is meestal genoeg om het probleem bij de eerste poging te reproduceren.",
    uk: "Корисний звіт про помилку потребує трьох речей: що ви зробили, чого очікували і що сталося натомість. Додайте свій браузер і версію, а також значення HEX, якщо проблема стосується конкретного кольору — зазвичай цього достатньо, щоб відтворити проблему з першої спроби.",
    vi: "Một báo cáo lỗi hữu ích cần ba điều: bạn đã làm gì, bạn mong đợi điều gì, và điều gì đã xảy ra thay vào đó. Thêm trình duyệt và phiên bản của bạn, cùng giá trị HEX nếu sự cố liên quan đến một màu cụ thể — điều này thường đủ để tái hiện sự cố ngay lần thử đầu tiên.",
    th: "รายงานข้อบกพร่องที่มีประโยชน์ต้องการสามสิ่ง: คุณทำอะไร คุณคาดหวังอะไร และเกิดอะไรขึ้นแทน เพิ่มเบราว์เซอร์และเวอร์ชันของคุณ และค่า HEX หากปัญหาเกี่ยวข้องกับสีที่เฉพาะเจาะจง — โดยทั่วไปก็เพียงพอที่จะทำให้เกิดปัญหาซ้ำได้ในครั้งแรก",
    id: "Laporan bug yang berguna membutuhkan tiga hal: apa yang Anda lakukan, apa yang Anda harapkan, dan apa yang terjadi sebagai gantinya. Tambahkan browser dan versi Anda, serta nilai HEX jika masalah melibatkan warna tertentu — biasanya itu cukup untuk mereproduksi masalah pada percobaan pertama.",
    sv: "En användbar felrapport behöver tre saker: vad du gjorde, vad du förväntade dig och vad som hände istället. Lägg till din webbläsare och version, samt ett HEX-värde om problemet gäller en specifik färg — det räcker oftast för att återskapa problemet på första försöket."
  },
