  res_help_feature_body: {
    en: "Describe the problem you are trying to solve rather than the control you imagine — the task usually suggests a better solution than the first interface that comes to mind. Mention how often you hit it and what you do today as a workaround.",
    fr: "Décrivez le problème que vous cherchez à résoudre plutôt que le bouton que vous imaginez : la tâche suggère souvent une meilleure solution que la première interface qui vient à l'esprit. Précisez la fréquence à laquelle vous la rencontrez et votre contournement actuel.",
    ar: "صف المشكلة التي تريد حلّها بدل العنصر الذي تتخيّله؛ فالمهمة نفسها كثيرًا ما توحي بحلّ أفضل من أول واجهة تخطر بالبال. واذكر كم مرة تواجهها وما الحل البديل الذي تستخدمه الآن.",
    es: "Describe el problema que intentas resolver en lugar del control que imaginas — la tarea suele sugerir una solución mejor que la primera interfaz que se te ocurre. Menciona con qué frecuencia lo encuentras y qué haces hoy como solución alternativa.",
    de: "Beschreiben Sie das Problem, das Sie lösen möchten, anstatt das Bedienelement, das Sie sich vorstellen — die Aufgabe legt meist eine bessere Lösung nahe als die erste Oberfläche, die einem einfällt. Erwähnen Sie, wie oft Sie darauf stoßen und was Sie derzeit als Workaround tun.",
    it: "Descrivi il problema che stai cercando di risolvere piuttosto che il controllo che immagini — il compito di solito suggerisce una soluzione migliore della prima interfaccia che viene in mente. Menziona quanto spesso lo incontri e cosa fai oggi come soluzione alternativa.",
    pt: "Descreva o problema que você está tentando resolver, em vez do controle que imagina — a tarefa geralmente sugere uma solução melhor do que a primeira interface que vem à mente. Mencione com que frequência você encontra isso e o que faz hoje como solução alternativa.",
    zh: "请描述您想解决的问题，而不是您想象中的控件——任务本身通常能提示比脑海中第一个界面更好的解决方案。请说明您遇到这种情况的频率以及目前的应对方法。",
    ja: "想像しているコントロールではなく、解決したい課題を説明してください。多くの場合、その課題自体が最初に思いついたインターフェースよりも良い解決策を示唆します。どのくらいの頻度で遭遇するか、現在どのように回避しているかも教えてください。",
    ko: "상상하는 컨트롤이 아니라 해결하려는 문제를 설명하세요. 작업 자체가 처음 떠오르는 인터페이스보다 더 나은 해결책을 제시하는 경우가 많습니다. 얼마나 자주 겪는지, 현재 어떻게 우회하고 있는지도 언급해 주세요.",
    hi: "जो नियंत्रण आप कल्पना करते हैं उसके बजाय उस समस्या का वर्णन करें जिसे आप हल करने की कोशिश कर रहे हैं — कार्य आमतौर पर पहले दिमाग में आए इंटरफेस से बेहतर समाधान सुझाता है। बताएं कि आप इसे कितनी बार देखते हैं और आज इसके लिए क्या वर्कअराउंड करते हैं।",
    tr: "Hayal ettiğiniz kontrolü değil, çözmeye çalıştığınız sorunu tanımlayın — görev genellikle akla gelen ilk arayüzden daha iyi bir çözüm önerir. Ne sıklıkla karşılaştığınızı ve şu anda geçici çözüm olarak ne yaptığınızı belirtin.",
    pl: "Opisz problem, który próbujesz rozwiązać, a nie wyobrażoną kontrolkę — zadanie zwykle sugeruje lepsze rozwiązanie niż pierwszy pomysł na interfejs. Wspomnij, jak często się z tym spotykasz i co robisz obecnie jako obejście.",
    nl: "Beschrijf het probleem dat je probeert op te lossen in plaats van het besturingselement dat je je voorstelt — de taak suggereert meestal een betere oplossing dan de eerste interface die in je opkomt. Vermeld hoe vaak je dit tegenkomt en wat je nu als workaround doet.",
    uk: "Опишіть проблему, яку намагаєтесь вирішити, а не елемент керування, який ви уявляєте — завдання зазвичай підказує краще рішення, ніж перший інтерфейс, що спадає на думку. Зазначте, як часто ви з цим стикаєтесь і що робите зараз як обхідний шлях.",
    vi: "Hãy mô tả vấn đề bạn đang cố gắng giải quyết thay vì điều khiển bạn tưởng tượng — nhiệm vụ thường gợi ý một giải pháp tốt hơn so với giao diện đầu tiên nghĩ đến. Đề cập bạn gặp phải điều này bao lâu một lần và bạn đang làm gì để khắc phục tạm thời.",
    th: "อธิบายปัญหาที่คุณพยายามแก้ไขแทนที่จะเป็นตัวควบคุมที่คุณจินตนาการไว้ งานมักจะบ่งบอกถึงวิธีแก้ปัญหาที่ดีกว่าอินเทอร์เฟซแรกที่นึกถึง ระบุว่าคุณพบปัญหานี้บ่อยแค่ไหนและตอนนี้คุณแก้ไขปัญหาชั่วคราวอย่างไร",
    id: "Jelaskan masalah yang ingin Anda selesaikan, bukan kontrol yang Anda bayangkan — tugas biasanya menyarankan solusi yang lebih baik daripada antarmuka pertama yang terpikirkan. Sebutkan seberapa sering Anda mengalaminya dan apa yang Anda lakukan sekarang sebagai solusi sementara.",
    sv: "Beskriv problemet du försöker lösa istället för kontrollen du föreställer dig — uppgiften brukar antyda en bättre lösning än det första gränssnittet som dyker upp i huvudet. Nämn hur ofta du stöter på det och vad du gör idag som en tillfällig lösning."
  },
